import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/gem/commands.md","filePath":"en/modules/gem/commands.md","lastUpdated":0}`),a={name:`en/modules/gem/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>The main command of EmakiGem is <code>/emakigem</code>, with <code>/egem</code> and <code>/eg</code> as aliases. Commands are used to open gem GUIs, inspect gem state, clear debugging state, reload configuration, and print debug information.</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/emakigem help</code></td><td>none</td><td>Print the command help list. Also shown when running <code>/emakigem</code> with no arguments.</td></tr><tr><td><code>/emakigem gui &lt;inlay|upgrade|extract|reroll|recalibrate|open&gt;</code></td><td><code>emakigem.use</code> or <code>emakigem.admin</code></td><td>Open the selected gem GUI mode. The mode argument is required by the current command router; an unknown mode is treated as an argument error.</td></tr><tr><td><code>/emakigem reload</code></td><td><code>emakigem.reload</code> or <code>emakigem.admin</code></td><td>Reload config, gems, socket item definitions, resonances, conditions, GUI files, and language files.</td></tr><tr><td><code>/emakigem inspect [player]</code></td><td><code>emakigem.use</code> or <code>emakigem.admin</code></td><td>Inspect gem state on the held item of the target player or yourself.</td></tr><tr><td><code>/emakigem reroll &lt;full|value|confirm|cancel|status&gt;</code></td><td><code>emakigem.use</code> or <code>emakigem.admin</code></td><td>Generate or accept a reroll candidate for the gem in the <strong>main hand</strong>. See <a href="#reroll-commands">Reroll commands</a>.</td></tr><tr><td><code>/emakigem clearstate</code></td><td><code>emakigem.admin</code></td><td>Clear gem layer state from the held item. Useful for debugging or repairing abnormal items.</td></tr><tr><td><code>/emakigem convert-legacy [confirm]</code></td><td><code>emakigem.admin</code></td><td>Convert the deprecated <code>match</code> block in <code>items/*.yml</code> into <code>matcher</code> plus a top-level <code>slot_groups</code>. Gem has no key-rename targets left beyond that. Without an argument it only previews; <code>confirm</code> (or <code>--apply</code>) rewrites the files and leaves a <code>.bak</code> backup each. The converted <code>matcher</code> still needs a manual pass, see <a href="./templates.html#migrating-from-match">Socket item definitions</a>.</td></tr><tr><td><code>/emakigem debug</code></td><td><code>emakigem.debug</code> or <code>emakigem.admin</code></td><td>Print runtime debug information.</td></tr></tbody></table><h2 id="gui-modes" tabindex="-1">GUI modes <a class="header-anchor" href="#gui-modes" aria-label="Permalink to “GUI modes”">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Purpose</th></tr></thead><tbody><tr><td><code>inlay</code></td><td>Inlay gems. Extraction can be toggled from inside the view.</td></tr><tr><td><code>extract</code></td><td>Open directly in extract mode.</td></tr><tr><td><code>upgrade</code></td><td>Upgrade gems using EmakiStrengthen recipe materials.</td></tr><tr><td><code>reroll</code></td><td>Full reroll: re-roll the affixes of the main-hand gem.</td></tr><tr><td><code>recalibrate</code></td><td>Value reroll: re-roll only the values of existing affixes.</td></tr><tr><td><code>open</code></td><td>Open locked socket slots with socket openers.</td></tr></tbody></table><h2 id="reroll-commands" tabindex="-1">Reroll commands <a class="header-anchor" href="#reroll-commands" aria-label="Permalink to “Reroll commands”">​</a></h2><p>The <code>reroll</code> subcommands act on the gem in the <strong>main hand</strong> and require <code>emakigem.use</code> or <code>emakigem.admin</code>:</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Purpose</th></tr></thead><tbody><tr><td><code>full</code></td><td>Generate a full reroll candidate (re-rolls the affixes themselves) and charge <code>full_cost</code> immediately.</td></tr><tr><td><code>value</code></td><td>Generate a value reroll candidate (values only) and charge <code>value_cost</code> immediately.</td></tr><tr><td><code>confirm</code></td><td>Confirm the candidate and write it to the main-hand gem.</td></tr><tr><td><code>cancel</code></td><td>Abandon the candidate and refund the charge.</td></tr><tr><td><code>status</code></td><td>Show the current candidate&#39;s type, original affix count, candidate affix count, and remaining seconds.</td></tr></tbody></table><p>When an unfinished candidate session already exists, running <code>full</code> or <code>value</code> again returns that session without charging again or regenerating the candidate. Candidate lifetime is controlled by <code>reroll.session_ttl_seconds</code> in <code>config.yml</code>. Configuration and settlement rules are in <a href="./gems.html#reroll">Gem Definitions</a>.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakigem gui inlay</span></span>
<span class="line"><span>/emakigem gui open</span></span>
<span class="line"><span>/emakigem gui upgrade</span></span>
<span class="line"><span>/emakigem reroll full</span></span>
<span class="line"><span>/emakigem reroll confirm</span></span>
<span class="line"><span>/emakigem inspect Steve</span></span>
<span class="line"><span>/emakigem reload</span></span></code></pre></div><p>Gem items should be distributed through item sources, shops, rewards, or other server-side systems.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};